#!/usr/bin/env python3
"""Measure whether the reports that FACTS entries cite name the tests that the entries name.
Run from the repository root: python3 tmp/test-names-in-reports/measure.py > tmp/test-names-in-reports/out.json"""
import re, os, glob, json, sys, collections, statistics
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from split import entries, sentences

ROOT = os.getcwd()
PF = 'ProjectFortress'
TF = ['tests', 'compiler_tests', 'other_compiler_tests', 'one_library_tests', 'compiler_regressions',
      'library_tests', 'parser_tests', 'linker_tests', 'syntax_abstraction_tests', 'not_passing_yet',
      'not_working_compiler_tests', 'not_working_library_tests', 'not_working_static_tests', 'test_library']
# a test sentence starts with one of these
TEST_START = re.compile(r'^(Gated\b|Tests?:|Tests\b|No (gated )?(test|program)|No test|Plain tests gate|The test that checks|The ties are gated)')
NOTEST = re.compile(r'^No (gated )?(test|program)')

JUNIT = {}
for p in glob.glob(PF + '/src/**/*Test*.java', recursive=True) + glob.glob(PF + '/src/**/*JUTest*.java', recursive=True):
    JUNIT[os.path.basename(p)[:-5]] = p
FILES = {}  # folder -> set of stems
for f in TF:
    st = set()
    for p in glob.glob(f'{PF}/{f}/**/*', recursive=True):
        b = os.path.basename(p)
        if '.' in b:
            st.add(b.rsplit('.', 1)[0])
    FILES[f] = st

def strip(tok):
    t = tok.strip().rstrip('.,;:')
    if t.startswith('ProjectFortress/'): t = t[len('ProjectFortress/'):]
    if t.startswith('src/com/sun/fortress/'): t = t[len('src/com/sun/fortress/'):]
    t = re.sub(r'\.(fss|test|java|sh|fsi)$', '', t)
    return t

def resolve(folder, stem):
    """files matched: list of 'folder/stem'"""
    folders = [folder] if folder else TF
    rx = re.compile('^' + re.escape(stem).replace(r'\*', '[A-Za-z0-9_]*') + '$')
    out = []
    for f in folders:
        out += [f'{f}/{s}' for s in FILES[f] if rx.match(s)]
    if not out and not folder:
        out += ['junit/' + s for s in JUNIT if rx.match(s)]
    return sorted(set(out))

LOOKS = re.compile(r'^[A-Za-z_*][A-Za-z0-9_*]*$')

def test_names(sentence):
    """Return list of dicts {tok, folder, stem, pattern, files}."""
    names = []
    folder = None
    for tok in re.findall(r'`([^`]+)`', sentence):
        t = strip(tok)
        if '/' in t:
            parts = t.split('/')
            if parts[0] in TF and len(parts) == 2:
                folder = parts[0]; stem = parts[1]
                if not LOOKS.match(stem): continue
                names.append(dict(tok=tok, folder=folder, stem=stem, pattern='*' in stem, files=resolve(folder, stem)))
            elif parts[-1] in JUNIT or parts[-1].endswith('JUTest'):
                names.append(dict(tok=tok, folder='junit', stem=parts[-1], pattern=False,
                                  files=['junit/' + parts[-1]] if parts[-1] in JUNIT else []))
            elif tok.endswith('.py') and 'test' in os.path.basename(tok):
                p = tok if os.path.exists(tok) else None
                names.append(dict(tok=tok, folder='tool', stem=os.path.basename(tok)[:-3], pattern=False,
                                  files=[tok] if p else []))
            continue
        if not LOOKS.match(t) or not re.search(r'[A-Z]', t) or not re.search(r'[a-z]', t) or len(t.replace('*', '')) < 6:
            continue
        if t in JUNIT:
            names.append(dict(tok=tok, folder='junit', stem=t, pattern=False, files=['junit/' + t])); continue
        files = resolve(folder, t) if folder else []
        if not files:
            files = resolve(None, t)
        if files or folder:
            names.append(dict(tok=tok, folder=folder or (files[0].split('/')[0] if files else None),
                              stem=t, pattern='*' in t, files=files))
    return names

# ---- reports ----
def resolve_path(p, prev_dir):
    p = p.strip().rstrip('.,;:')
    for c in [p, 'explorations/' + p, os.path.join(prev_dir or '', p)]:
        if c and os.path.isfile(c): return c
    return None

def parse_md(path):
    lines = open(path, encoding='utf-8', errors='replace').read().split('\n')
    heads = []  # (lineidx, level, text)
    fence = False
    for i, l in enumerate(lines):
        if l.startswith('```'): fence = not fence; continue
        if fence: continue
        m = re.match(r'^(#{1,6})\s+(.*)$', l)
        if m: heads.append((i, len(m.group(1)), m.group(2).strip()))
    secs = []
    for k, (i, lv, tx) in enumerate(heads):
        end = len(lines); leaf_end = len(lines)
        for (j, lv2, _) in heads[k + 1:]:
            if leaf_end == len(lines): leaf_end = j
            if lv2 <= lv: end = j; break
        secs.append(dict(start=i, level=lv, head=tx, text='\n'.join(lines[i:end]), leaf='\n'.join(lines[i:leaf_end])))
    return '\n'.join(lines), secs

MDCACHE = {}
def md(path):
    if path not in MDCACHE: MDCACHE[path] = parse_md(path)
    return MDCACHE[path]

def norm(h):
    h = re.sub(r'[`"*]', '', h).strip().lower()
    return h

def find_heading(secs, want):
    w = norm(want)
    eq = [s for s in secs if norm(s['head']) == w]
    if eq: return eq[0]
    # strip numbering from heading
    eq = [s for s in secs if re.sub(r'^(section\s+)?[0-9a-z]+(\.[0-9]+)*[.:)]?\s+', '', norm(s['head'])) == w]
    if eq: return eq[0]
    hold = [s for s in secs if w in norm(s['head'])]
    return hold[0] if hold else None

def find_numbered(secs, num):
    n = num.lower().rstrip('.')
    rx = re.compile(r'^(section\s+|part\s+|§\s*)?' + re.escape(n) + r'(\.|:|\)|\s|$)')
    c = [s for s in secs if rx.match(norm(s['head']))]
    if not c: return None
    # prefer exact level of numbering (shortest heading level)
    return sorted(c, key=lambda s: s['level'])[0]

def expand_nums(spec):
    """'1, 3 and 5' / '1 to 3' / 'A.1 and A.2.1' / 'B.1 to B.3 and B.6' -> list"""
    out = []
    for part in re.split(r',\s*|\s+and\s+', spec):
        part = part.strip()
        if not part: continue
        m = re.match(r'^([A-Z]\.)?(\d+)\s+to\s+([A-Z]\.)?(\d+)$', part)
        if m:
            pre = m.group(1) or ''
            for k in range(int(m.group(2)), int(m.group(4)) + 1): out.append(pre + str(k))
            continue
        if re.match(r'^([A-Z](\.\d+)*|\d+(\.\d+)*)$', part): out.append(part)
    return out

def citations(detail):
    """Parse a Detail sentence into [(path_or_None, rawpath, [section specs])]; spec = ('head', text) | ('num', n) | ('whole',)"""
    body = re.sub(r'^Details?:\s*', '', detail)
    cites = []
    prev_dir = None
    # split into chunks at each backticked path ending in a doc extension
    toks = list(re.finditer(r'`([^`]+\.(?:md|tex|txt|tsv|tick))`', body))
    for k, m in enumerate(toks):
        raw = m.group(1)
        seg = body[m.end(): toks[k + 1].start() if k + 1 < len(toks) else len(body)]
        p = resolve_path(raw, prev_dir)
        if p: prev_dir = os.path.dirname(p)
        specs = []
        for q in re.findall(r'"([^"]+)"', seg): specs.append(('head', q))
        segnq = re.sub(r'"[^"]*"', '', seg)
        for sm in re.finditer(r'\bsections?\s+((?:[A-Z]\.)?\d+(?:\.\d+)*(?:(?:,\s*|\s+and\s+|\s+to\s+)(?:[A-Z]\.)?\d+(?:\.\d+)*)*)', segnq):
            for n in expand_nums(sm.group(1)): specs.append(('num', n))
        segns = re.sub(r'\bsections?\s+[\d.,A-Z ]+(and|to)?[\d. ]*', '', segnq)
        for sm in re.finditer(r'(?:^|\s)((?:[A-Z]\.\d+(?:\.\d+)*)(?:(?:,\s*|\s+and\s+|\s+to\s+)[A-Z]\.\d+(?:\.\d+)*)*)', segns):
            for n in expand_nums(sm.group(1)): specs.append(('num', n))
        cites.append((p, raw, specs))
    return cites

WORD = lambda s: re.compile(r'(?<![A-Za-z0-9_])' + s + r'(?![A-Za-z0-9_])')

def named_in(name, text):
    """Is the test named in text? same token/pattern, or every file of the pattern named."""
    stem = name['stem']
    if name['pattern']:
        if stem in text: return True
        if not name['files']: return False
        return all(WORD(re.escape(f.split('/')[-1])).search(text) for f in name['files'])
    return bool(WORD(re.escape(stem)).search(text))

def named_in_any(name, text):
    if not name['pattern']: return named_in(name, text)
    if name['stem'] in text: return True
    return any(WORD(re.escape(f.split('/')[-1])).search(text) for f in name['files'])

def main():
    E = entries()
    facts_len = len(open('explorations/coordinator/FACTS.md', encoding='utf-8').read())
    res = []
    for fid, line in E:
        ss = sentences(line)
        tsent = [x for x in ss[1:] if TEST_START.match(x)]
        dsent = [x for x in ss[1:] if re.match(r'Details?:', x)]
        names = []
        for t in tsent:
            for n in test_names(t):
                if not any(n['stem'] == m['stem'] and n['folder'] == m['folder'] for m in names): names.append(n)
        # outside test sentences, mentions of test paths
        other = [n for x in ss[1:] if x not in tsent and not x.startswith('Detail') for n in test_names(x) if n['folder'] in TF and '/' in n['tok']]
        if names: kind = 'names'
        elif any(NOTEST.match(t) for t in tsent): kind = 'notest'
        elif tsent: kind = 'testsentence-no-name'
        else: kind = 'nothing'
        r = dict(id=fid, kind=kind, tsent=tsent, tchars=sum(len(t) + 1 for t in tsent), entry_len=len(line) + 1,
                 names=names, other_mentions=len(other), detail=dsent)
        cites = []
        for d in dsent: cites += citations(d)
        r['cites'] = []
        for p, raw, specs in cites:
            c = dict(raw=raw, path=p, specs=specs, secs=[], missing_secs=[])
            if p and p.endswith('.md'):
                full, secs = md(p)
                c['size'] = len(full)
                for sp in specs:
                    s = find_heading(secs, sp[1]) if sp[0] == 'head' else find_numbered(secs, sp[1])
                    if s: c['secs'].append(s['head'])
                    else: c['missing_secs'].append(sp[1])
            elif p:
                c['size'] = len(open(p, encoding='utf-8', errors='replace').read())
                c['nonmd'] = True
            r['cites'].append(c)
        # classification
        if kind == 'names':
            reports = [c for c in r['cites'] if c['path']]
            if not r['cites']:
                cls = 'no-report-cited'
            else:
                bad = [c for c in r['cites'] if not c['path'] or c['missing_secs']]
                sec_text = ''; rep_text = ''
                for c in reports:
                    if c.get('nonmd'):
                        t = open(c['path'], encoding='utf-8', errors='replace').read(); rep_text += t; sec_text += t; continue
                    full, secs = md(c['path'])
                    rep_text += full + '\n'
                    if not c['specs']: sec_text += full + '\n'  # whole report cited
                    for h in c['secs']:
                        s = [x for x in secs if x['head'] == h][0]; sec_text += s['text'] + '\n'
                in_sec = [named_in(n, sec_text) for n in names]
                in_rep = [named_in(n, rep_text) for n in names]
                in_rep_any = [named_in_any(n, rep_text) for n in names]
                r['n_in_sec'] = sum(in_sec); r['n_in_rep'] = sum(in_rep); r['n_in_rep_any'] = sum(in_rep_any)
                r['missing_names'] = [n['stem'] for n, ok in zip(names, in_rep) if not ok]
                if all(in_sec): sub = 'A-in-cited-section'
                elif all(in_rep): sub = 'B-in-report-not-cited-section'
                else: sub = 'C-some-missing'
                r['sub'] = sub
                cls = 'D-cited-report-or-section-missing' if bad else sub
                # where in the reports: leaf sections holding each name
                where = []
                for c in reports:
                    if c.get('nonmd'): continue
                    full, secs = md(c['path'])
                    for n in names:
                        leafs = [s for s in secs if named_in_any(n, s['leaf'])]
                        for s in leafs: where.append((c['path'], s['head'], s['level'], len(s['leaf']), n['stem']))
                r['where'] = where
                # one section holding all tests (any level >=2) per report
                best = None
                for c in reports:
                    if c.get('nonmd'): continue
                    full, secs = md(c['path'])
                    hold = [n for n in names if named_in(n, full)]
                    if len(hold) < len(names): continue
                    cand = [s for s in secs if s['level'] >= 2 and all(named_in(n, s['text']) for n in names)]
                    if cand:
                        s = min(cand, key=lambda s: len(s['text']))
                        if best is None or len(s['text']) < best[2]: best = (c['path'], s['head'], len(s['text']), s['level'])
                r['one_section'] = best
                # leaf-section spread: minimal set of distinct leaf sections (greedy) per report with most names
                leafsets = collections.defaultdict(set)
                for (p, h, lv, sz, st) in where: leafsets[(p, h, sz)].add(st)
                need = set(n['stem'] for n in names if any(st == n['stem'] for (_, _, _, _, st) in where))
                chosen = []
                while need:
                    k = max(leafsets, key=lambda k: (len(leafsets[k] & need), -k[2]))
                    if not leafsets[k] & need: break
                    chosen.append(k); need -= leafsets[k]
                r['leaf_cover'] = [(p, h, sz) for (p, h, sz) in chosen]
        else:
            cls = kind
        r['cls'] = cls
        res.append(r)
    json.dump(dict(facts_len=facts_len, entries=res), sys.stdout, indent=1, default=str)

if __name__ == '__main__':
    main()

